const names=['YOU','KOJO','NII','KOFI'];
const colors=[0xc05336,0x326b85,0xb59546,0x468367];
export function footballVariant(ctx){const C={fourcorners:FourCorners,penalties:Penalties,onepole:OnePole,laski:Laski}[ctx.game.id];return C?new C(ctx):null;}

export class Penalties extends Mode{
 constructor(ctx){super(ctx);this.goalSpec=goalSpec(this.settings.goalStyle,2.4);this.goal=goalFrame(0,-9,0,-1,5.5,this.goalSpec.height,this.goalSpec);this.goalMesh=streetGoal(this.root,0,-9,Math.PI/2,5.5,this.goalSpec.height,this.goalSpec.style);this.surfaceType=pitchType(this.game.id,this.settings.pitchSurface);this.surface=pitchTypes[this.surfaceType];pitchSurface(this.root,15,24,this.surfaceType);chalk(this.root,0,-9,5.5,.06);chalk(this.root,0,0,.2,.2);for(const x of [-5,5])chalk(this.root,x,-5,.04,8);chalk(this.root,0,-1,10,.04);
  this.you=this.player(-.7,3.2);this.cpu=this.player(0,-8.7,0x326b85);this.b=ball(this.root);this.v=new THREE.Vector3();this.target=ringTarget(this.root);this.aimX=0;this.aimY=Math.min(.7,this.goal.height*.5);this.scores=[0,0];this.shots=[0,0];this.history=[[],[]];this.turn=0;this.charge=null;this.control=this.settings.penaltyControl==='aim'?'aim':'timing';this.cameraWide=false;this.prepare();
 }
 setView(){this.world.setCamera(this.cameraWide?[12,12,9,0,.7,-4]:this.turn===0?[1.4,3.4,8.3,0,1,-6]:[0,3.2,-12,0,1,0]);this.goalMesh.userData.netHidden=this.turn===1&&!this.cameraWide;}
 cycleCamera(){this.cameraWide=!this.cameraWide;this.setView();}
 prepare(){this.phase='aim';this.time=0;this.b.position.set(0,.12,0);this.v.set(0,0,0);this.dive=0;this.diveAge=0;this.diveActive=false;this.saved=false;this.charge=null;this.goalX=0;for(const p of [this.you,this.cpu]){p.userData.pose='idle';p.userData.jump=0;p.userData.lean=0;p.userData.run=0;}
  this.shooter=this.turn===0?this.you:this.cpu;this.keeper=this.turn===0?this.cpu:this.you;this.shooter.position.set(-.7,0,3.2);this.shooter.rotation.y=Math.PI;this.keeper.position.set(0,0,-8.7);this.keeper.rotation.y=0;this.keeper.userData.pose='keeperReady';this.setView();
  if(this.turn===0){this.setActions(this.control==='timing'?[{id:'lock',label:'Lock aim',key:'Space'}]:[{id:'shoot',label:'Hold / shoot',key:'Space',charge:true}]);this.note(this.control==='timing'?'Watch the moving target. Lock aim, then stop the power meter.':'Aim at the goal. Hold Shoot for power; release to begin your run-up.');this.world.aimPlane=new THREE.Plane(new THREE.Vector3(0,0,1),9);}
  else{this.cpuAim=(Math.random()-.5)*4.8;this.cpuHeight=.16+Math.random()*(this.goal.height-.34);this.releaseAt=1.5+Math.random()*.6;this.setActions([{id:'left',label:'Dive left',key:'Q'},{id:'center',label:'Stay centre',key:'Space'},{id:'right',label:'Dive right',key:'E'}]);this.note('Your turn in goal. Choose a side, or react after the strike. Left/right follow your view.');this.world.aimPlane=null;}
 }
 hold(){if(this.turn===0&&this.phase==='aim'&&this.control==='aim')this.charge=this.age;}
 action(id){if(this.turn===0){if(this.phase==='aim'&&this.control==='timing'){this.phase='power';this.time=0;this.power=.1;this.setActions([{id:'shoot',label:'Set power',key:'Space'}]);this.note('Stop the power meter. Too much lift can clear the bar.');}else if(this.phase==='power'){const power=this.power;this.launch(this.aimX,this.goal.height<1.4?.16+power*.25:.35+power*1.65+(power>.9?(power-.9)*7:0),power);}else if(this.phase==='aim'){const power=this.charge===null?.5:clamp((this.age-this.charge)/1.1,.15,1);this.launch(this.aimX,this.aimY,power);this.charge=null;}}else if(['aim','runup','flight'].includes(this.phase)&&!this.dive&&['left','right','center'].includes(id)){const left=this.cameraWide?-1:1;this.dive=id==='left'?left:id==='right'?-left:2;if(this.phase==='flight')this.diveActive=true;}}
 launch(x,y,power){this.pendingShot={x,y,power};this.phase='runup';this.time=0;this.shooter.userData.run=.7;this.note('RUN-UP');}
 strike(){const {x,y,power}=this.pendingShot,duration=.95-power*.45;this.phase='flight';this.time=0;this.v.set(x/duration,(y-.12+4.905*duration*duration)/duration,-9/duration);this.shooter.userData.run=0;this.shooter.userData.kick=.24;this.ui.sound('kick');const read=this.settings.difficulty==='hard'?.65:this.settings.difficulty==='easy'?.4:.52;this.cpuReact=(this.settings.difficulty==='hard'?.18:this.settings.difficulty==='easy'?.29:.23)+Math.random()*.1;const chosen=Math.random()<read?(Math.sign(x)||1):-(Math.sign(x)||1);this.cpuDive=Math.abs(x)<.4&&Math.random()<.45?0:chosen*(1.9+Math.random()*.6);this.diveActive=this.turn===1&&!!this.dive;this.diveAge=0;}
 hit({point}){if(this.turn===0&&this.phase==='aim'&&this.control==='aim'){this.aimX=clamp(point.x,-3.3,3.3);this.aimY=clamp(point.y,.15,3.1);}}
 resolve(goal,message){if(this.phase==='result')return;this.shots[this.turn]++;this.history[this.turn].push(goal);if(goal)this.scores[this.turn]++;this.phase='result';this.time=0;this.note(message);this.ui.sound(goal?'goal':'miss');this.ui.penaltyScores?.(this.history);}
 updateDive(dt){const k=this.keeper;if(!this.networked&&this.turn===0&&this.phase==='flight'&&this.time>this.cpuReact&&!this.diveActive){this.diveActive=true;this.dive=this.cpuDive<-.35?-1:this.cpuDive>.35?1:2;this.diveAge=0;}if(!this.diveActive)return;this.diveAge+=dt;const progress=clamp(this.diveAge/.48,0,1),side=this.dive===2?0:this.dive,destination=this.turn===0&&!this.networked?this.cpuDive:side*2.25;k.position.x=THREE.MathUtils.lerp(0,destination,1-(1-progress)**2);k.userData.pose=side?'keeperDive':'keeperReady';k.userData.lean=-side*Math.sin(clamp(this.diveAge/.48,0,1)*Math.PI/2)*1.35;k.userData.jump=Math.sin(clamp(this.diveAge/.85,0,1)*Math.PI)*.48;k.userData.diveSide=side;}
 update(dt){this.status(`YOU ${this.scores[0]} — ${this.scores[1]} THEM`,`${this.turn?'SAVE':'SHOOT'} · ${this.shots[0]} / ${this.shots[1]} TAKEN`);this.ui.penaltyScores?.(this.history);this.target.visible=this.turn===0&&['aim','power'].includes(this.phase);
  if(this.phase==='aim'&&(this.turn===0||this.networked)){if(this.control==='timing'){this.aimX=Math.sin(this.time*1.7)*2.55;this.aimY=Math.min(.85,this.goal.height*.5);}else{const input=this.input.vector();this.aimX=clamp(this.aimX+input.x*dt*2,-3.3,3.3);this.aimY=clamp(this.aimY-input.z*dt*1.5,.15,3.1);}this.ui.power?.(this.charge===null?0:clamp((this.age-this.charge)/1.1,0,1));}
  if(this.phase==='power'){this.power=.1+.9*(.5-.5*Math.cos(this.time*4));this.ui.power?.(this.power);}if(this.target.visible)this.target.position.set(this.aimX,this.aimY,-8.96);
  if(!this.networked&&this.phase==='aim'&&this.turn===1&&this.time>this.releaseAt)this.launch(this.cpuAim,this.cpuHeight,.5+Math.random()*.3);
  if(this.phase==='runup'){const f=clamp(this.time/.78,0,1);this.shooter.position.set(THREE.MathUtils.lerp(-.7,-.26,f),0,THREE.MathUtils.lerp(3.2,.5,f));if(this.time>.62&&this.time-dt<=.62)this.shooter.userData.kick=.38;if(this.time>=.78)this.strike();return;}
  this.updateDive(dt);
  if(this.phase==='flight'){const before=stepBall(this.b,this.v,dt,{drag:this.surface.drag,bounce:this.surface.bounce}),post=collideGoalFrames(this.b,this.v,before,[this.goal]);if(post){this.ui.sound('stone');this.note('Off the frame!');}
   const crossing=before.z>=-8.7&&this.b.position.z<=-8.7;if(!this.saved&&crossing){const t=(-8.7-before.z)/(this.b.position.z-before.z),p=before.clone().lerp(this.b.position,t),reach=this.diveActive?.58:.34;if(Math.abs(p.x-this.keeper.position.x)<reach&&p.y<(this.diveActive&&this.dive!==2?1.12:1.72)+(this.keeper.userData.jump||0)){this.saved=true;this.v.z=Math.abs(this.v.z)*.5;this.v.y=2;this.resolve(false,'SAVED! The keeper reached the shot.');return;}}
   if(!post&&crossedGoal(before,this.b.position,this.goal))this.resolve(true,'GOAL!');else if(this.b.position.z<-9.3||this.time>2)this.resolve(false,'Wide, over, or off the frame. No goal.');
  }else if(this.phase==='result'){if(this.time<.5){stepBall(this.b,this.v,dt,{drag:2,bounce:.3});if(this.b.position.z<-10.1){this.b.position.z=-10.1;this.v.z=Math.abs(this.v.z)*.12;this.v.x*=.3;}}if(this.time>1.5){const winner=shootoutWinner(this.shots,this.scores);if(winner!==null){this.score=this.scores[0];return this.finish(winner===0?'SHOOTOUT WON':'SHOOTOUT LOST',`${this.scores[0]}–${this.scores[1]} from ${this.shots[0]} / ${this.shots[1]} kicks.`,winner===0);}this.turn=1-this.turn;this.prepare();}}
 }
}

export class OnePole extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([2.6,4.6,14,0,.7,-1]);this.players=[this.player(-1,8),this.player(1,-8,0x326b85)];this.you=this.players[0];this.players[0].rotation.y=Math.PI;this.poles=[];for(const z of [-10,10]){const pole=goalMarker(this.root,this.settings.poleStyle||'sticks',1.35);pole.position.z=z;pole.rotation.z=.025;this.poles.push(pole);chalk(this.root,0,z>0?7:-7,4,.04);}this.b=ball(this.root);this.v=new THREE.Vector3();this.target=this.circle(0,-10,.25);this.scores=[0,0];this.shots=[0,0];this.turn=0;this.phase='aim';this.aim=0;this.charge=null;this.stance=0;this.cameraView=0;this.surfaceType=pitchType('onepole',this.settings.pitchSurface);this.surface=pitchTypes[this.surfaceType];pitchSurface(this.root,8.8,25,pitchType('onepole',this.settings.pitchSurface));this.prepare();}
 prepare(){this.phase='aim';this.time=0;this.charge=null;this.b.position.set(this.turn?0:this.stance,.12,this.turn?-8:8);this.players[this.turn].position.set(this.b.position.x-.45,0,this.turn?-9.5:9.5);this.players[1-this.turn].position.x=1.5;this.players.forEach(p=>p.userData.run=0);this.aimed=this.aim;this.v.set(0,0,0);this.setActions(this.turn?[{id:'wait',label:'Their shot',key:'Space',disabled:true}]:[{id:'shoot',label:'Hold / strike',key:'Space',charge:true},{id:'left',label:'Step left',key:'Q'},{id:'right',label:'Step right',key:'E'}]);this.note(this.turn?'Their turn. Only a direct hit on your pole scores.':'Aim at the far pole. Hold Strike for pace; release to kick. Q/E changes your starting position; C changes camera. Watch the moving aim mark. Six shots each; most pole hits wins.');}
 hold(){if(this.turn===0&&this.phase==='aim')this.charge=this.age;}
 action(id){if(this.turn||this.phase!=='aim')return;if(id==='left'||id==='right'){this.stance=clamp(this.stance+(id==='left'?-.45:.45),-2.7,2.7);this.b.position.x=this.stance;this.players[0].position.x=this.stance-.45;return;}this.launch(this.aimed??this.aim,this.charge===null?.55:clamp((this.age-this.charge)/1.1,.15,1));this.charge=null;}
 launch(aim,power){this.phase='runup';this.time=0;this.pendingShot={aim,power};this.kickerStart=this.players[this.turn].position.clone();this.players[this.turn].userData.run=.55;}
 strike(){const {aim,power}=this.pendingShot;this.phase='flight';this.time=0;this.players[this.turn].userData.run=0;const direction=this.turn?1:-1;this.v.set(Math.sin(aim)*(12+power*13),.35,direction*Math.cos(aim)*(12+power*13));this.players[this.turn].userData.kick=.38;this.ui.sound('kick');}
 hit({point}){if(!this.turn&&this.phase==='aim')this.aim=clamp(Math.atan2(point.x-this.stance,8-point.z),-.3,.3);}
 resolve(hit){if(this.phase!=='flight')return;this.shots[this.turn]++;if(hit){this.scores[this.turn]++;this.poles[this.turn?1:0].rotation.z=.18;}this.phase='result';this.time=0;this.note(hit?'Direct pole hit — one point.':'Miss. Crossing the end line does not score.');this.ui.sound(hit?'point':'miss');}
 cycleCamera(){this.cameraView=(this.cameraView+1)%3;}
 update(dt){const direction=this.turn?1:-1;const lookZ=this.phase==='flight'?this.b.position.z*.65:0;this.world.setCamera(this.cameraView===1?[10,13,5,0,.4,lookZ]:this.cameraView===2?[0,18,4,0,0,0]:[1.6,4.3,-direction*14,0,.45,lookZ]);this.status(`YOU ${this.scores[0]} — ${this.scores[1]} THEM`,`${this.turn?'THEIR':'YOUR'} SHOT · ${this.shots[this.turn]+1} / 6`);if(this.phase==='aim'){if(!this.turn||this.networked){this.aim=clamp(this.aim+this.input.vector().x*dt*.18,-.3,.3);this.aimed=this.aim+Math.sin(this.age*1.9)*.012;this.target.position.set(this.stance+Math.tan(this.aimed)*18,.035,-10);this.target.visible=true;this.ui.power?.(this.charge===null?.55:clamp((this.age-this.charge)/1.1,0,1));}else if(this.time>1.5)this.launch((Math.random()-.5)*.045,.6+Math.random()*.3);}else if(this.phase==='runup'){this.target.visible=false;const f=clamp(this.time/.65,0,1),p=this.players[this.turn];p.position.copy(this.kickerStart).lerp(new THREE.Vector3(this.b.position.x-.2,0,this.b.position.z-direction*.4),f);if(this.time>.5)p.userData.kick=.3;if(this.time>=.65)this.strike();}else if(this.phase==='flight'){const before=stepBall(this.b,this.v,dt,{drag:this.surface.drag*.3,bounce:this.surface.bounce}),z=this.turn?10:-10,spec=goalSpec(this.settings.poleStyle||'sticks',1.35),p=new THREE.Vector3(0,clamp(this.b.position.y,0,spec.postHeight),z);if(sweptDistance(before,this.b.position,p)<.12+spec.postRadius&&this.b.position.y<spec.postHeight+.12)this.resolve(true);else if(Math.abs(this.b.position.z)>11||Math.abs(this.b.position.x)>4||this.time>4)this.resolve(false);}else if(this.time>1.5){if(this.shots.every(x=>x>=6)){this.score=this.scores[0];this.finish(this.score===this.scores[1]?'LEVEL ON POLE HITS':this.score>this.scores[1]?'ONE POLE WON':'THEY TAKE THE DUEL',`${this.score}–${this.scores[1]} direct hits from six shots each.`,this.score>=this.scores[1]);}else{this.turn=1-this.turn;this.poles.forEach(p=>p.rotation.z=.025);this.prepare();}}}
}

export class Laski extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([2,7,14,0,.6,-2]);this.cameraView=0;this.playBounds={x:12,z:15};this.goalSpec=goalSpec(this.settings.goalStyle,2.2);this.goal=goalFrame(0,-9,0,-1,5,this.goalSpec.height,this.goalSpec);this.goalMesh=streetGoal(this.root,0,-9,Math.PI/2,5,this.goalSpec.height,this.goalSpec.style);this.surfaceType=pitchType('laski',this.settings.pitchSurface);this.surface=pitchTypes[this.surfaceType];pitchSurface(this.root,18,24,pitchType('laski',this.settings.pitchSurface));for(const [x,z,w,d]of [[0,-9,16,.035],[-8,0,.035,18],[8,0,.035,18],[0,9,16,.035]])chalk(this.root,x,z,w,d);this.players=[this.player(0,5),this.player(-3,1,0x326b85),this.player(3,1,0xb59546),this.player(0,-2,0x468367)];this.players.forEach((p,i)=>p.userData.id=i);this.you=this.players[0];this.keeper=this.player(0,-8.2,0xc5c0a1);this.keeper.rotation.y=0;this.active=[true,true,true,true];this.b=ball(this.root);this.v=new THREE.Vector3();this.lastTouch=-1;this.phase='serve';this.cool=0;this.possessor=null;this.charge=null;this.keeperRole=false;this.selectedOut=1;this.you.rotation.y=Math.PI;this.marker=this.circle(0,5,.48);this.setPlayingActions();this.serve();}
 setPlayingActions(){this.setActions(this.keeperRole?[{id:'throw',label:'Throw in',key:'Space',charge:true},{id:'dive',label:'Dive / save',key:'E'}]:[{id:'shoot',label:'Shoot / tackle',key:'Space',charge:true},{id:'volley',label:'Volley',key:'E'},{id:'sprint',label:'Sprint',key:'Shift',hold:true}]);}
 serve(){this.dive=0;for(const p of [...this.players,this.keeper]){p.userData.run=0;p.userData.dribble=0;p.userData.lateral=0;}this.phase='serve';this.time=0;this.possessor=null;this.lastTouch=-1;this.keeper.userData.lean=0;this.keeper.userData.jump=0;this.b.position.set(this.keeper.position.x,1.2,-7.8);this.v.set(0,0,0);this.charge=null;this.note(this.keeperRole?'You are keeping. Throw the ball into the players.':'The keeper throws in. Win the ball and score to choose who leaves.');}
 throwIn(){this.phase='play';this.time=0;this.v.set((Math.random()-.5)*3,5.5,8);this.keeper.userData.pose='keeperThrow';this.keeper.userData.throwUntil=this.age+.55;this.cool=.5;this.ui.sound('swing');}
 hold(){if(['play','serve'].includes(this.phase))this.charge=this.age;}
 action(id){if(this.phase==='choose'){if(id.startsWith('out-'))this.eliminate(Number(id.slice(4)));return;}if(this.phase==='winner'){if(id==='keeper'||id==='player')this.newGame(id==='keeper');else if(id==='continue')this.nextRound();return;}if(this.keeperRole){if(this.phase==='serve'&&id==='throw')this.throwIn();else if(this.phase==='play'){this.dive=.8;this.diveDirection=Math.sign(this.input.vector().x)||Math.sign(this.b.position.x-this.keeper.position.x)||1;this.keeper.userData.pose='keeperDive';}return;}if(this.phase!=='play'||!this.active[0])return;
  if(this.possessor&&this.possessor!==this.you){if(distance(this.you,this.possessor)<1.35){this.possessor=null;this.cool=.1;this.v.set(Math.sin(this.you.rotation.y)*4,.4,Math.cos(this.you.rotation.y)*4);this.ui.sound('kick');}return;}
  if(distance(this.you,this.b)<1.2&&this.b.position.y<(id==='volley'?2.2:.85)){const raw=this.world.movementVector?.(this.input.vector())||this.input.vector(),power=this.charge===null?.5:clamp((this.age-this.charge)/1.1,.1,1),aim=Math.abs(raw.x)>.15?raw.x*2.15:(this.keeper.position.x>=0?-1.8:1.8);this.strike(0,clamp(aim,-2.15,2.15),power,id==='volley');}this.charge=null;
 }
 strike(i,targetX,power=.6,volley=false){const p=this.players[i],d=new THREE.Vector3(targetX,.5,-10).sub(this.b.position);d.y=0;this.v.copy(d.normalize().multiplyScalar(13+power*10));this.v.y=volley?1.1:this.goal.height<1.4?.25:1.2+power;this.possessor=null;this.lastTouch=i;this.cool=.3;p.userData.kick=.38;this.ui.sound('kick');}
 scored(i){if(!this.active[i]||i<0)return;this.lastScorer=i;this.phase='choose';this.time=0;this.v.set(0,0,0);this.possessor=null;this.ui.sound('goal');const others=this.active.flatMap((a,j)=>a&&j!==i?[j]:[]);if(i===0&&!this.keeperRole){this.setActions(others.map((j,k)=>({id:'out-'+j,label:'Eliminate '+names[j],key:['Space','E','Q'][k]})));this.note('You scored. Choose ONE player to eliminate.');}else{this.selectedOut=others.slice().sort((a,b)=>distance(this.players[a],this.keeper)-distance(this.players[b],this.keeper))[0];this.note(`${this.playerName(i)} scored and is choosing a player to eliminate.`);}}
 eliminate(i){if(this.phase!=='choose'||!this.active[i]||i===this.lastScorer)return false;this.active[i]=false;this.players[i].visible=false;const remaining=this.active.flatMap((a,j)=>a?[j]:[]);if(i===0&&!this.keeperRole&&!this.networked){this.score=4-remaining.length;this.finish('ELIMINATED BY THE SCORER',`${this.playerName(this.lastScorer)} chose you after scoring. ${remaining.length} players remain.`,false);return true;}if(remaining.length===1){this.phase='winner';this.time=0;this.winner=remaining[0];if(this.online){this.score=this.winner===0?3:0;this.finish(this.winner===0?'LASKI CHAMPION':'LASKI COMPLETE','Challenge round complete. Compare scores in Friends & Scores.',this.winner===0);return true;}this.ui.roundComplete?.({score:this.winner===0?3:0,success:this.winner===0});if(this.winner===0&&!this.keeperRole){this.setActions([{id:'keeper',label:'Be keeper next',key:'Space'},{id:'player',label:'Play again',key:'E'}]);this.note('You are the last player. Choose keeper or player for the next game.');}else{this.nextKeeper=Math.random()<.5;this.setActions([{id:'continue',label:'Next game',key:'Space'}]);this.note(`${this.playerName(this.winner)} wins and chooses to ${this.nextKeeper?'keep':'play again'}.`);}}else{this.setPlayingActions();this.serve();}return true;}
 playerName(i){return i===0&&this.keeperRole?'KWESI':names[i];}
 nextRound(){if(this.nextKeeper&&this.keeperRole){const winner=this.players[this.winner];this.players[this.winner]=this.keeper;this.keeper=winner;[this.players[0],this.players[this.winner]]=[this.players[this.winner],this.players[0]];this.keeperRole=false;}this.newGame(this.nextKeeper?false:this.keeperRole);}
 newGame(keeperRole){this.ui.roundStarted?.();if(keeperRole&&!this.keeperRole)[this.keeper,this.players[0]]=[this.players[0],this.keeper];this.keeperRole=keeperRole;this.active=[true,true,true,true];for(let i=0;i<4;i++){this.players[i].userData.id=i;this.players[i].visible=true;this.players[i].position.set([-3,3,-3,3][i],0,[4,4,0,0][i]);}this.keeper.position.set(0,0,-8.2);this.keeper.rotation.y=0;this.keeper.visible=true;this.you=keeperRole?this.keeper:this.players[0];this.setPlayingActions();this.serve();}
 cycleCamera(){this.cameraView=(this.cameraView+1)%3;this.world.setCamera([[2,7,14,0,.6,-2],[12,12,7,0,.4,-2],[0,21,5,0,0,-2]][this.cameraView]);}
 hit({point,id}){if(this.phase==='choose'&&typeof id==='number')this.eliminate(id);else this.input.target=point;}
 update(dt){this.cool=Math.max(0,this.cool-dt);this.status(`${this.active.filter(Boolean).length} PLAYERS LEFT`,this.phase==='winner'?'WINNER CHOOSES NEXT ROLE':this.phase==='choose'?'SCORER CHOOSES ELIMINATION':this.keeperRole?'YOU ARE KEEPING':'ONE KEEPER · EVERY PLAYER FOR THEMSELVES');
  if(this.phase==='winner'){if(this.winner!==0||this.keeperRole){if(this.time>3)this.nextRound();}return;}
  if(this.phase==='choose'){if(!this.networked&&(this.lastScorer!==0||this.keeperRole)&&this.time>1.5)this.eliminate(this.selectedOut);return;}
  if(this.phase==='serve'){this.keeper.userData.pose='keeperHold';this.b.position.set(this.keeper.position.x,1.2,-7.8);if(!this.networked&&!this.keeperRole&&this.time>1.8)this.throwIn();return;}
  const previousKeeperX=this.keeper.position.x;
  if(this.keeperRole){const v=this.input.vector();this.keeper.position.x=clamp(this.keeper.position.x+v.x*dt*5,-2.5,2.5);this.keeper.position.z=-8.3;this.dive=Math.max(0,(this.dive||0)-dt);this.keeper.userData.pose=this.dive?'keeperDive':this.age<(this.keeper.userData.throwUntil||0)?'keeperThrow':'keeperReady';if(this.dive){this.keeper.position.x=clamp(this.keeper.position.x+(this.diveDirection||1)*dt*3.5,-2.8,2.8);this.keeper.userData.lean=-(this.diveDirection||1)*Math.sin((.8-this.dive)/.8*Math.PI)*1.3;this.keeper.userData.jump=Math.sin((.8-this.dive)/.8*Math.PI)*.35;}else{this.keeper.userData.lean=0;this.keeper.userData.jump=0;}}else{const raw=this.world.movementVector?.(this.input.vector())||this.input.vector(),target=!raw.x&&!raw.z&&this.input.target?this.input.target:{x:this.you.position.x+raw.x*3,z:this.you.position.z+raw.z*3};this.you.userData.run=moveActor(this.you,target,this.input.sprint?7:5,dt);this.marker.position.set(this.you.position.x,.03,this.you.position.z);if(!this.networked)this.keeper.position.x=THREE.MathUtils.damp(this.keeper.position.x,clamp(this.b.position.x*.65,-2,2),2.2,dt);this.keeper.userData.pose=this.age<(this.keeper.userData.throwUntil||0)?'keeperThrow':'keeperReady';if(!this.networked&&this.v.z<-1&&this.b.position.z<-5){this.keeper.userData.pose='keeperDive';this.keeper.userData.lean=-Math.sign(this.b.position.x-this.keeper.position.x)*.85;}else this.keeper.userData.lean=0;}
  this.keeper.userData.lateral=this.keeper.position.x-previousKeeperX;this.keeper.userData.run=Math.min(1,Math.abs(this.keeper.userData.lateral)/Math.max(dt*3.5,.001));
  const field=this.players.filter((p,i)=>this.active[i]),carrier=this.possessor,challenger=closestChallenger(field,carrier,this.b,this.keeperRole?null:this.you);for(const p of field)if(p!==carrier)p.userData.dribble=0;
  for(let i=0;i<4;i++){
   if(this.networked||!this.active[i]||i===0&&!this.keeperRole)continue;
   const p=this.players[i];p.userData.pose='idle';let target,speed=4.1;
   if(p===carrier){
    const lane=this.keeper.position.x>=0?-1.8:1.8;
    target={x:lane*1.4,z:-5.8};speed=4.5;
    if(challenger&&distance(p,challenger)<1.4)target.x=clamp(p.position.x+(p.position.x>=challenger.position.x?1.5:-1.5),-6,6);
    p.userData.carryTime=(p.userData.carryTime||0)+dt;
    if(this.cool<=0&&p.userData.carryTime>.45&&p.position.z<-1.5&&p.position.z>-7.7){this.strike(i,lane,.6);p.userData.carryTime=0;}
   }else{p.userData.carryTime=0;target=p===challenger?(carrier?{x:carrier.position.x+Math.sin(carrier.rotation.y)*.65,z:carrier.position.z+Math.cos(carrier.rotation.y)*.65}:this.b.position):supportPosition(p,carrier,this.b,i,true);}
   p.userData.run=moveActor(p,target,speed,dt);
  }
  separatePlayers(field,.9,this.playBounds);
  if(!this.networked&&carrier&&this.possessor===carrier&&challenger&&(challenger!==this.you||this.keeperRole)&&this.cool<=0&&distance(challenger,this.b)<.72){
   this.possessor=challenger;this.lastTouch=challenger.userData.id;challenger.userData.carryTime=0;this.cool=.7;this.ui.sound('kick');
  }
  if(this.possessor){const p=this.possessor;dribbleBall(this.b,p,dt,this.age);this.v.set(0,0,0);this.lastTouch=p.userData.id;}else{const prev=stepBall(this.b,this.v,dt,{drag:this.surface.drag,bounce:this.surface.bounce}),post=collideGoalFrames(this.b,this.v,prev,[this.goal]);if(post){this.cool=.22;this.ui.sound('stone');this.note('Off the post — play the rebound.');}if(prev.z>=-8.3&&this.b.position.z<-8.3&&Math.abs(this.b.position.x-this.keeper.position.x)<(this.dive?.95:.65)&&this.b.position.y<2&&this.v.z<0){this.v.z=Math.abs(this.v.z)*.7;this.v.y=2.5;this.lastTouch=-1;this.cool=.25;this.ui.sound('ballHit');this.note('Saved — the rebound is live.');}else if(!post&&crossedGoal(prev,this.b.position,this.goal)&&this.lastTouch>=0){this.scored(this.lastTouch);return;}
   if(this.cool<=0&&this.b.position.y<.7){const nearest=field.slice().sort((a,b)=>distance(a,this.b)-distance(b,this.b))[0];if(nearest&&distance(nearest,this.b)<.75){this.possessor=nearest;this.lastTouch=nearest.userData.id;nearest.userData.carryTime=0;this.cool=.5;}}
  }
  // Chalk lines do not end a Laski rally. Keep distant balls reachable at the compound edge.
  for(const axis of ['x','z']){const edge=this.playBounds[axis]+.3;if(Math.abs(this.b.position[axis])>edge){this.b.position[axis]=Math.sign(this.b.position[axis])*edge;this.v[axis]=-Math.sign(this.b.position[axis])*Math.abs(this.v[axis])*.45;}}this.ui.power?.(this.charge===null?0:clamp((this.age-this.charge)/1.1,0,1));
 }
}
